solution:
import java.util.ArrayList;
class Tarea { String titulo; boolean completa; Tarea(String t) { titulo=t; } }
public class Main {
    public static void main(String[] args) {
        ArrayList<Tarea> ts=new ArrayList<>(); ts.add(new Tarea("Leer")); ts.add(new Tarea("Practicar")); ts.get(0).completa=true;
        for(Tarea t:ts) System.out.println(t.titulo + ": " + (t.completa ? "Hecho" : "Pendiente"));
    }
}
